#!/usr/bin/env python3
# Гл. 4, пакет G: G1 (крупные места) + G2 (сентенции/ремарки/дубли). Каждая замена — ровно 1 вхождение.
import pathlib
p = pathlib.Path("03-manuscript/arc-01/ch-04.md")
t = p.read_text(encoding="utf-8")
n = 0
def rep(old, new):
    global t, n
    c = t.count(old); assert c == 1, f"count={c}: {old[:70]!r}"
    t = t.replace(old, new); n += 1

